import { auth } from "@/auth";
import { readEntitlements } from "@/lib/entitlements";
import { ThemeAccessSync } from "@/components/theme";
import { cache } from "react";

export const readThemeAccess = cache(async () => {
  let allowed = false;
  let deadline: string | null = null;
  try {
    const session = await auth();
    if (session?.user?.id) {
      const access = await readEntitlements(session.user.id);
      allowed = access.features.blackThemes;
      deadline = access.accessDeadline;
    }
  } catch {
    // Public pages remain usable with Free themes when access cannot be verified.
  }
  return { allowed, deadline };
});

export async function ThemeAccess() {
  const { allowed, deadline } = await readThemeAccess();
  return <ThemeAccessSync allowed={allowed} deadline={deadline} />;
}
